using System;using System.Linq;using UnityEngine;
public static class ReviewB2Sword {
 public static object Run(){var source=UnityEngine.Object.FindObjectsByType<Animator>(FindObjectsInactive.Include,FindObjectsSortMode.None).First(a=>a.name.StartsWith("Meshy_AI_lowpoly_paladin")&&a.gameObject.scene.name=="3DBattleScene");var root=UnityEngine.Object.Instantiate(source.gameObject);root.hideFlags=HideFlags.HideAndDontSave;root.SetActive(true);root.transform.SetPositionAndRotation(new Vector3(1000,0,1000),Quaternion.identity);var a=root.GetComponent<Animator>();a.enabled=false;var clip=a.runtimeAnimatorController.animationClips[0];var camObject=new GameObject("B2 review camera");camObject.hideFlags=HideFlags.HideAndDontSave;var cam=camObject.AddComponent<Camera>();cam.enabled=false;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.22f,.24f,.28f);cam.fieldOfView=40;var rt=new RenderTexture(440,500,24);cam.targetTexture=rt;var tex=new Texture2D(1320,500,TextureFormat.RGB24,false);var previous=RenderTexture.active;float gripError=0;try{var skin=root.GetComponentInChildren<SkinnedMeshRenderer>();var hand=root.GetComponentsInChildren<Transform>().First(t=>t.name=="RightHand");var sword=root.GetComponentsInChildren<Transform>().First(t=>t.name=="B2 Holy Sword");var attach=hand.Find("Holy Sword Grip");for(int i=0;i<3;i++){clip.SampleAnimation(a.gameObject,clip.length*i/3f);gripError=Mathf.Max(gripError,Vector3.Distance(attach.position,sword.TransformPoint(new Vector3(0,0,-.0075f))));var baked=UnityEngine.Object.Instantiate(skin.sharedMesh);var v=baked.vertices;var w=baked.boneWeights;var mm=skin.bones.Select((b,j)=>b.localToWorldMatrix*baked.bindposes[j]).ToArray();for(int j=0;j<v.Length;j++){var p=v[j];var b=w[j];v[j]=mm[b.boneIndex0].MultiplyPoint3x4(p)*b.weight0+mm[b.boneIndex1].MultiplyPoint3x4(p)*b.weight1+mm[b.boneIndex2].MultiplyPoint3x4(p)*b.weight2+mm[b.boneIndex3].MultiplyPoint3x4(p)*b.weight3;}baked.vertices=v;baked.RecalculateNormals();baked.RecalculateBounds();var draw=new GameObject("Review body");draw.AddComponent<MeshFilter>().sharedMesh=baked;draw.AddComponent<MeshRenderer>().sharedMaterials=skin.sharedMaterials;skin.enabled=false;var target=root.transform.position+Vector3.up*1.1f;cam.transform.position=target+new Vector3(3.7f,1.4f,4.5f);cam.transform.LookAt(target);cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,440,500),440*i,0);skin.enabled=true;UnityEngine.Object.DestroyImmediate(draw);UnityEngine.Object.DestroyImmediate(baked);}tex.Apply();System.IO.File.WriteAllBytes("Assets/3DBattle/Authoring~/B2SwordReview.png",tex.EncodeToPNG());return new{gripError,clip=clip.name};}finally{RenderTexture.active=previous;cam.targetTexture=null;UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(camObject);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}}
}
